N=17; c=N//2; grid=[[0]*N for _ in range(N)]
for r in range(c+1):
    grid[r][c-r]=2; grid[r][c+r]=2
for r in range(N):
    for k in range(N):
        rr=3+2*k; cc=c-1-2*k
        # stripe begins at (rr,cc), then goes down-right; restrict to actual image bounds
        y=max(rr, -cc+rr) # maybe just enumerate based on equation
        d=c-4-4*k
        for y in range(N):
            x=y+d
            if y>=rr and 0<=x<N and grid[y][x]==0: grid[y][x]=1
print('\n'.join(' '.join(map(str,row)) for row in grid))
